const item = $input.first().json.body || $input.first().json;

// Context Expansion check
const isShort = (item.content || '').length < 150;
item.expansion_instruction = isShort 
  ? 'Sumber sangat ringkas. Wajib lakukan rekonstruksi konteks sejarah artis bersangkutan, latar belakang perselisihan masa lalu, dan uraikan spektrum sentimen warganet secara kaya minimal 1000 kata.'
  : 'Kembangkan narasi kronologi berimbang berdasarkan fakta sumber.';

return [{ json: item }];

